            if sp > 0 {
                let rid = str_slice(line, 0, sp)
                let rname = str_slice(line, sp + 1, len(line))
                if !dict_has(ids, rid) {
                    dict_set(ids, rid, 1)
                    roster = arr_push(roster, Entry { id: rid, name: rname, best: -1 })
                }
            }
        }
    }

    let best = dict_new()
    let seen = dict_new()
    let ignored = 0
    let slines = str_split(scores_text, "\n")
    for i in 0..len(slines) {
        let line = slines[i]
        if len(line) > 0 {
            if !dict_has(seen, line) {
                dict_set(seen, line, 1)
                let comma = str_index_of(line, ",")
                if comma >= 0 {
                    let sid = str_slice(line, 0, comma)
                    match parse_int(str_slice(line, comma + 1, len(line))) {
                        Ok(sc) => {
                            if dict_has(ids, sid) {
                                let cur = dict_get_or(best, sid, -1)
                                if sc > cur {
                                    dict_set(best, sid, sc)
                                }
                            } else {
                                ignored = ignored + 1
                            }
                        }
                        Err(_) => {
                            0
                        }
                    }
                }
            }
        }
    }

    let final = arr_repeat(Entry { id: "", name: "", best: -1 }, 0)
    for i in 0..len(roster) {
        let e = roster[i]
        final = arr_push(final, Entry { id: e.id, name: e.name, best: dict_get_or(best, e.id, -1) })
    }

    let scored = arr_filter(final, |e| e.best >= 0)
    let unscored = arr_filter(final, |e| e.best < 0)
    let sorted = arr_sort_by(scored, |a, b| if a.best > b.best { -1 } else { if a.best < b.best { 1 } else { str_cmp(a.id, b.id) } })

    let out = ""
    for i in 0..len(sorted) {
        let s = sorted[i]
        out = out + to_str(i + 1) + ". " + s.name + " " + to_str(s.best) + "\n"
    }
    for i in 0..len(unscored) {
        let u = unscored[i]
        out = out + u.name + " -\n"
    }

    match write_file("./out/ranking.txt", out) {
        Ok(_) => {
            println("ignored: {to_str(ignored)}")
            0
        }
        Err(e) => {
            eprintln("cannot write: {e}")
            1
        }
    }
}
